const cp = require('child_process');

class MIPSVM {
    constructor(elfPath) {
        this.elfBuffer = fs.readFileSync(elfPath);
        // Registers: 32 general purpose registers ($0 - $31), PC, HI, LO
        this.regs = new Int32Array(32);
        this.pc = 0x400110;
        this.hi = 0;
        this.lo = 0;

        // Memory: 64KB pages in a Map, or a Uint8Array covering 0x400000 to 0x4500000 (70MB), 
        // plus page tables or a large Buffer for high bss if needed.
        // Wait, max address accessed by DOOM objects is ~0x404b178d (around 68MB).
        // Let us allocate a Uint8Array of size 0x5000000 (80MB) starting at virtual address 0x400000.
        // Wait, let us map base 0x400000 to 0x4B00000 (75MB).
        this.memBase = 0x400000;
        this.memSize = 0x10000000; // 256MB
        this.mem = new Uint8Array(this.memSize);

        this.loadELF();

        // Setup stack pointer ($sp = 0x4750c0 or similar high bss / stack region)
        // In MIPS executables, the stack can be set to near the top of allocated memory, e.g. 0x07400000 or 0x04700000 or 0x4750c000.
        // Let us check where _start expects $sp or how argc/argv are set up.
    }

    loadELF() {
        const elf = this.elfBuffer;
        const e_phoff = elf.readUInt32LE(0x1c);
        const e_phentsize = elf.readUInt16LE(0x2a);
        const e_phnum = elf.readUInt16LE(0x2c);
        this.entry = elf.readUInt32LE(0x18);
        this.pc = this.entry;

        for (let i = 0; i < e_phnum; i++) {
            const ph = elf.subarray(e_phoff + i * e_phentsize, e_phoff + (e_phentsize));
            const type = ph.readUInt32LE(0);
            if (type === 1) { // PT_LOAD
                const offset = ph.readUInt32LE(4);
                const vaddr = ph.readUInt32LE(8);
                const filesz = ph.readUInt32LE(16);
                const memsz = ph.readUInt32LE(20);

                const destOffset = vaddr - this.memBase;
                if (destOffset >= 0 && destOffset + memsz <= this.memSize) {
                    if (filesz > 0) {
                        this.mem.set(elf.subarray(offset, offset + filesz), destOffset);
                    }
                    // BSS (memsz > filesz) is already zeroed by Uint8Array initialization.
                    console.log(`Loaded PT_LOAD: vaddr=0x${vaddr.toString(16)}, filesz=0x${filesz.toString(16)}, memsz=0x${memsz.toString(16)}`);
                } else {
                    console.error(`PT_LOAD out of memory bounds: vaddr=0x${vaddr.toString(16)}, memsz=0x${memsz.toString(16)}`);
                }
            }
        }
    }

    read32(addr) {
        const off = addr - this.memBase;
        if (off >= 0 && off <= this.memSize - 4) {
            return (this.mem[off] | (this.mem[off+1] << 8) | (this.mem[off+2] << 16) | (this.mem[off+3] << 24)) >>> 0;
        }
        throw new Error(`Read out of bounds at 0x${addr.toString(16)}`);
    }

    write32(addr, val) {
        const off = addr - this.memBase;
        if (off >= 0 && off <= this.memSize - 4) {
            this.mem[off]   = val & 0xff;
            this.mem[off+1] = (val >> 8) & 0xff;
            this.mem[off+2] = (val >> 16) & 0xff;
            this.mem[off+3] = (val >> 24) & 0xff;
            return;
        }
        throw new Error(`Write out of bounds at 0x${addr.toString(16)}`);
    }

    read16(addr) {
        const off = addr - this.memBase;
        if (off >= 0 && off <= this.memSize - 2) {
            return (this.mem[off] | (this.mem[off+1] << 8)) & 0xffff;
        }
        throw new Error(`Read16 out of bounds at 0x${addr.toString(16)}`);
    }

    write16(addr, val) {
        const off = addr - this.memBase;
        if (off >= 0 && off <= this.memSize - 2) {
            this.mem[off]   = val & 0xff;
            this.mem[off+1] = (val >> 8) & 0xff;
            return;
        }
        throw new Error(`Write16 out of bounds at 0x${addr.toString(16)}`);
    }

    read8(addr) {
        const off = addr - this.memBase;
        if (off >= 0 && off < this.memSize) {
            return this.mem[off];
        }
        throw new Error(`Read8 out of bounds at 0x${addr.toString(16)}`);
    }

    write8(addr, val) {
        const off = addr - this.memBase;
        if (off >= 0 && off < this.memSize) {
            this.mem[off] = val & 0xff;
            return;
        }
        throw new Error(`Write8 out of bounds at 0x${addr.toString(16)}`);
    }
}

